export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-1 stage 1: fix B3+B4, B6, F3 in parallel, then one verify pass',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const PARKED = { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
  options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
  recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
  genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
  done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
  required: ['question','header','options','default','reason','genuine','gated','files','stop'] }
const VERDICTS = { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: {
  ticket: {type:'string'}, passed: {type:'boolean'}, evidence: {type:'string'}, why: {type:'string'}, parked: PARKED },
  required: ['ticket','passed','evidence'] } } }, required: ['verdicts'] }

const common = args.common
phase('Fix')
const reports = await parallel(args.items.map(it => () =>
  agent(`${common}\n\nYOUR ITEM ONLY (other agents are working the other items in parallel in the same tree - touch only your files):\n\n${it.text}`,
    { label: `AAAB fix:${it.id}`, phase: 'Fix' })))

phase('Verify')
const summary = args.items.map((it, i) => `### ${it.id}\n${it.text}\n\nFixer report:\n${reports[i] ?? '(agent died - no report)'}`).join('\n\n')
const v = await agent(`You verify stage AAAB of RUN-1 in the shelf repo (Python). Do NOT edit any file; do not commit. Three fixers worked these items in parallel:\n\n${summary}\n\nFor each ticket (B3, B4, B6, F3 - one verdict each): read the actual diff (git diff, plus untracked test files via git status), run \`python -m pytest -q\` yourself, and check the behaviour the ticket asks for directly (e.g. a python -c one-liner, and for B6 run \`python -m shelf list --json\` on an empty shelf and json.loads it). passed=true only if a check you ran proves it; evidence names the command and its output. Check nothing outside the named files changed and data/ is untouched. If a report says PARKED: check that the independent part works, check (git diff) that the gated files hold no partial guess, judge whether the decision is genuinely the user's, and list every file the gated part would touch; parked.files is the union of yours and the fixer's.`,
  { label: 'AAAB verify:all', phase: 'Verify', schema: VERDICTS })
return { reports, verdicts: v }

